// Simula una BD con lista en memoria para poder ejecutar
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

// Clase que representa un usuario
class Usuario {
   private int id;
   private String nombre;
   private String apellido;

   // Constructor
   public Usuario(int id, String nombre, String apellido) {
      this.id = id;
      this.nombre = nombre;
      this.apellido = apellido;
   }

   // Getters y setters
   public int getId() { return id; }
   public void setId(int id) { this.id = id; }
   public String getNombre() { return nombre; }
   public void setNombre(String nombre) { this.nombre = nombre; }
   public String getApellido() { return apellido; }
   public void setApellido(String apellido) { this.apellido = apellido; }
}

// Clase que representa la base de datos
class BaseDeDatos {
   private List<Usuario> usuarios;

   // Constructor
   public BaseDeDatos() {
      usuarios = new ArrayList<>();
   }

   // Método para crear un usuario
   public void crearUsuario(Usuario usuario) {
      usuarios.add(usuario);
   }

   // Método para leer un usuario
   public Usuario leerUsuario(int id) {
      for (Usuario usuario : usuarios) {
         if (usuario.getId() == id) {
            return usuario;
         }
      }
      return null;
   }

   // Método para actualizar un usuario
   public void actualizarUsuario(Usuario usuario) {
      for (int i = 0; i < usuarios.size(); i++) {
         if (usuarios.get(i).getId() == usuario.getId()) {
            usuarios.set(i, usuario);
            return;
         }
      }
   }

   // Método para eliminar un usuario
   public void eliminarUsuario(int id) {
      for (int i = 0; i < usuarios.size(); i++) {
         if (usuarios.get(i).getId() == id) {
            usuarios.remove(i);
            return;
         }
      }
   }
}

public class Main {
   public static void main(String[] args) {
      // Crear una instancia de la base de datos
      BaseDeDatos baseDeDatos = new BaseDeDatos();

      // Crear un usuario
      Usuario usuario = new Usuario(1, "Juan", "Pérez");

      // Agregar el usuario a la base de datos
      baseDeDatos.crearUsuario(usuario);

      // Leer el usuario de la base de datos
      Usuario usuarioLeido = baseDeDatos.leerUsuario(1);

      // Imprimir el usuario leído
      System.out.println("Usuario leído: " + usuarioLeido.getNombre() + " " + usuarioLeido.getApellido());
   }
}
